    try (XmlCursor cur = testElt.newCursor()) {
        cur.toFirstContentToken();
        cur.insertChars("Random mixed content");
        //move past child1
        cur.toNextToken();
        cur.toNextToken();
        cur.toNextToken();
        cur.insertChars("Random mixed content1");
        assertTrue(testElt.validate(createOptions()));
        assertEquals("<xml-fragment>Random mixed content" + "<child1>0</child1>Random mixed content1<child2>5</child2>" + "<child3>1</child3></xml-fragment>", testElt.xmlText());
        //to child1
        cur.toPrevToken();
        cur.toPrevToken();
        cur.toPrevToken();
        cur.toPrevToken();
        assertEquals(XmlCursor.TokenType.START, cur.currentTokenType());
        assertTrue(cur.removeXml());
        assertNull(testElt.getChild1());
        assertEquals("<xml-fragment>Random mixed content" + "Random mixed content1<child2>5</child2>" + "<child3>1</child3></xml-fragment>", testElt.xmlText());
    }
}

