@Test
void testMixedContentInvalid() throws Throwable {
    ExtendedMixedEltDocument doc = ExtendedMixedEltDocument.Factory.newInstance();
    ExtendedMixedT elt = doc.addNewExtendedMixedElt();
    elt.setExtendedAttr("FOOBAR_val");
    elt.setChild1(new BigInteger("10"));
    try (XmlCursor cur = elt.newCursor()) {
        cur.toFirstContentToken();
        cur.beginElement("Child2");
        cur.toNextToken();
        cur.insertChars("2");
        elt.setChild3(BigInteger.ONE);
        cur.toFirstContentToken();
        cur.toEndToken();
        cur.toNextToken();
        cur.toNextToken();
        cur.insertChars(" SOME CDATA HERE");
    }
    String expected = "<com:ExtendedMixedElt extendedAttr=\"FOOBAR_val\" " + "xmlns:com=\"http://xbean/scomp/derivation/ComplexExtension\">" + "<Child2/>" + "2" + "<child1>10</child1>" + " SOME CDATA HERE" + "<child3>1</child3>" + "</com:ExtendedMixedElt>";
    assertEquals(expected, doc.xmlText());
    XmlOptions validateOptions = createOptions();
    assertFalse(doc.validate(validateOptions));
    //TODO: Order check: is this the right errors? last one seems redundant given second-to-last
    //need ch1, ch2
    String[] errExpected = new String[] { XmlErrorCodes.ELEM_COMPLEX_TYPE_LOCALLY_VALID$EXPECTED_DIFFERENT_ELEMENT, XmlErrorCodes.ELEM_COMPLEX_TYPE_LOCALLY_VALID$EXPECTED_DIFFERENT_ELEMENT, XmlErrorCodes.ELEM_COMPLEX_TYPE_LOCALLY_VALID$MISSING_ELEMENT };
