@Test
void testEnumRestrictionScomp() throws Exception {
    String xsdAsString = "<?xml version="1.0" encoding="UTF-8" ?>
" + "
" + "<xs:schema xmlns:xs="http://www.w3.org/2001/XMLSchema">
" + "
" + " <xs:element name="ActionTypeElem" type="ACTION_TYPE" />
" + " <xs:element name="VIPActionTypeElem" type="VIP_ACTION_TYPE" />
" + "
" + " <xs:simpleType name="ACTION_TYPE">
" + "  <xs:restriction base="xs:string">
" + "   <xs:enumeration value="PROVIDE"/>
" + "   <xs:enumeration value="MODIFY"/>
" + "   <xs:enumeration value="CEASE"/>
" + "  </xs:restriction>
" + " </xs:simpleType>
" + "
" + " <xs:simpleType name="VIP_ACTION_TYPE">
" + "  <xs:restriction base="ACTION_TYPE">
" + "   <xs:enumeration value="QUERY"/>
" + "  </xs:restriction>
" + " </xs:simpleType>
" + "
" + "</xs:schema>";
    // load schema file as SchemaDocument XmlObject
    SchemaDocument sd = SchemaDocument.Factory.parse(xsdAsString);
