@ParameterizedTest
@ValueSource(strings = { // From XQTS cvshead June 2009
// K2-SeqExprCast-207: Construct an xs:anyURI from an invalid string. However, in F&O 17.1.1, it is said that "For xs:anyURI, the extent to which an implementation validates the lexical form of xs:anyURI is implementation dependent.".
"http:\\\\invalid>URI\\someURI", // K2-SeqExprCast-210: '%' is not a disallowed character and therefore it's not encoded before being considered for RFC 2396 validness.
"http://www.example.com/file%GF.html", // K2-SeqExprCast-421: Pass an invalid anyURI.
"foo://", // K2-SeqExprCast-421-2: Pass an invalid anyURI.
"foo:", // K2-SeqExprCast-422: Pass an invalid anyURI(#2).
"%gg", // K2-SeqExprCast-423: no scheme
":/cut.jpg", // K2-SeqExprCast-424: An URI without scheme, combined with a relative directory.
":/images/cut.png", // K2-SeqExprCast-505: ':/' is an invalid URI, no scheme.
":/", // fn-resolve-uri-4: Evaluation of resolve-uri function with an invalid URI value for second argument.
"http:%%", // fn-resolve-uri-3: Evaluation of resolve-uri function with an invalid URI value for first argument.
":", "###Rel", "##", "????###", "###????" })
void testLexAnyUriInvalid(String urIs) {
    assertThrows(InvalidLexicalValueException.class, () -> XsTypeConverter.lexAnyURI(urIs), "URI should be invalid");
}

