/**
 * Method testCopyDifferentStoresLoadedFromFile
 * Tests copy from document w/ namespaces to doc w/o
 */
@Test
void testCopyDifferentStoresLoadedFromFile() throws XmlException, IOException {
    try (XmlCursor xc0 = jcur(Common.TRANXML_FILE_CLM);
        XmlCursor xc1 = jcur("xbean/xmlcursor/po.xml")) {
        xc0.selectPath(Common.CLM_NS_XQUERY_DEFAULT + " .//Initial");
        xc0.toNextSelection();
        String sQuery = "declare namespace po=\"http://xbean.test/xmlcursor/PurchaseOrder\"; " + ".//po:zip";
        xc1.selectPath(sQuery);
        xc1.toNextSelection();
        // should copy the <Initial>GATX</Initial> element plus the default namespace
        xc0.copyXml(xc1);
        xc1.toPrevSibling();
        // verify xc1
        String sExpected = "<ver:Initial " + "xmlns:po=\"http://xbean.test/xmlcursor/PurchaseOrder\" " + "xmlns:ver=\"http://www.tranxml.org/TranXML/Version4.0\">" + "GATX</ver:Initial>";
        assertEquals(sExpected, xc1.xmlText());
        // verify xc0
        // should contain all the namespaces for the document
        assertEquals("<Initial xmlns=\"" + Common.CLM_NS + "\" " + Common.CLM_XSI_NS + ">GATX</Initial>", xc0.xmlText());
    }
}

