@Test
void testIf() throws Exception {
    String sXML = "<root>" + "<book price='20'>Pooh</book>" + "<cd price='25'>Pooh</cd>" + "<book price='50'>Maid</book>" + "<cd price='25'>Maid</cd>" + "</root>";
    String query1 = "if (//book[1]/@price) " + "  then //book[1] " + "  else 0";
    String query2 = "for $b1 in //book, $b2 in //cd " + "return " + "if ( $b1/@price < $b2/@price )" + " then $b1" + " else $b2";
    try (XmlCursor c = cur(sXML)) {
        c.selectPath(query1);
        assertEquals(1, c.getSelectionCount());
        c.toNextSelection();
        assertEquals("<book price=\"20\">Pooh</book>", c.xmlText());
        c.selectPath(query2);
        assertEquals(4, c.getSelectionCount());
        c.toNextSelection();
        assertEquals("<book price=\"20\">Pooh</book>", c.xmlText());
        c.toNextSelection();
        assertEquals("<book price=\"20\">Pooh</book>", c.xmlText());
        c.toNextSelection();
        assertEquals("<cd price=\"25\">Pooh</cd>", c.xmlText());
        c.toNextSelection();
        assertEquals("<cd price=\"25\">Maid</cd>", c.xmlText());
    }
}

