@Test
void testFunctionPathWithCursor() throws Exception {
    String sXml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>" + "<!-- My Comment -->" + "<employees xmlns=\"http://xmlbeans.apache.org/samples/xquery/employees\">\n" + "  <employee>\n" + "    <name>Fred Jones</name>\n" + "    <address location=\"home\">\n" + "      <street>900 Aurora Ave.</street>\n" + "      <city>Seattle</city>\n" + "      <state>WA</state>\n" + "      <zip>98115</zip>\n" + "    </address>\n" + "    <phone location=\"work\">(425)555-5665</phone>\n" + "    <phone location=\"home\">(206)555-5555</phone>\n" + "    <phone location=\"mobile\">(206)555-4321</phone>\n" + "  </employee>\n" + "  </employees>";
    XmlObject employees = XmlObject.Factory.parse(sXml);
    String m_namespaceDeclaration = "declare namespace xq='http://xmlbeans.apache.org/samples/xquery/employees';";
    try (XmlCursor cursor = employees.newCursor()) {
        cursor.toNextToken();
        cursor.selectPath(m_namespaceDeclaration + "$this//xq:employee");
        if (cursor.getSelectionCount() > 0) {
            cursor.toNextSelection();
            String[] names = new String[cursor.getSelectionCount()];
            for (int i = 0; i < cursor.getSelectionCount(); i++) {
                try (XmlCursor nameCursor = cursor.newCursor()) {
                    nameCursor.selectPath(m_namespaceDeclaration + "$this/xq:name/text()");
                    nameCursor.toNextSelection();
                    names[i] = nameCursor.getTextValue();
                }
                cursor.toNextSelection();
                System.out.println(names[i]);
            }
        }
    }
}

