@ParameterizedTest
@CsvSource(value = { "'<a><![CDATA[cdata text]]></a>'," + "'<a><![CDATA[cdata text]]></a>'," + "'<a><![CDATA[cdata text]]></a>'", // Bookmark doesn't seem to keep the length of the CDATA
// "<a>NL<b><![CDATA[cdata text]]> regular text</b>NL</a>," +
// "<a>\n<b>cdata text regular text</b>\n</a>," +
// "<a>NL  <b>cdata text regular text</b>NL</a>"
"'<a>\n<c>text <![CDATA[cdata text]]></c>\n</a>'," + "'<a>\n<c>text cdata text</c>\n</a>'," + "'<a>NL  <c>text cdata text</c>NL</a>'", // https://issues.apache.org/jira/browse/XMLBEANS-404
"'<a>\n<c>text <![CDATA[cdata text]]]]></c>\n</a>'," + "'<a>\n<c>text cdata text]]</c>\n</a>'," + "'<a>NL  <c>text cdata text]]</c>NL</a>'" })
void checkCData(String xmlText, String expected1, String expected2) throws XmlException {
    String NL = Stream.of(SystemProperties.getProperty("line.separator"), System.getProperty("line.separator"), "\n").filter(Objects::nonNull).findFirst().get();
    XmlOptions opts = new XmlOptions();
    opts.setUseCDataBookmarks();
    XmlObject xo = XmlObject.Factory.parse(xmlText.replace("NL", NL), opts);
    String result1 = xo.xmlText(opts);
    assertEquals(expected1.replace("NL", NL), result1, "xmlText");
    opts.setSavePrettyPrint();
    String result2 = xo.xmlText(opts);
    assertEquals(expected2.replace("NL", NL), result2, "prettyPrint");
}

