@Test
void testValidationElementError() throws XmlException {
    String bobSchema = "<xs:schema
" + "   xmlns:xs='http://www.w3.org/2001/XMLSchema'
" + "   xmlns:bob='http://openuri.org/bobschema'
" + "   targetNamespace='http://openuri.org/bobschema'
" + "   elementFormDefault='qualified'>
" + "
" + "  <xs:complexType name='biff'>
" + "   <xs:complexContent>
" + "    <xs:extension base='bob:foo'>
" + "     <xs:sequence>
" + "       <xs:element name='a' minOccurs='0' maxOccurs='unbounded'/>
" + "     </xs:sequence>
" + "    </xs:extension>
" + "   </xs:complexContent>
" + "  </xs:complexType>
" + "" + "  <xs:complexType name='foo'>
" + "  </xs:complexType>
" + "" + "  <xs:element name='foo' type='bob:foo'>
" + "  </xs:element>
" + "" + "</xs:schema>
";
    String invalid = "<bob:foo xmlns:xsi='http://www.w3.org/2001/XMLSchema-instance' xmlns:bob='http://openuri.org/bobschema' " + "xsi:type='bob:biff'><bob:q/></bob:foo>";
    String[] schemas = { bobSchema };
    List<XmlError> errors = performValidation(schemas, invalid);
    assertNotNull(errors);
    assertFalse(errors.isEmpty());
    for (Object error : errors) {
        XmlValidationError xmlValError = (XmlValidationError) error;
        assertEquals(xmlValError.getErrorType(), XmlValidationError.INCORRECT_ELEMENT);
        assertEquals(xmlValError.getBadSchemaType().getName().getLocalPart(), "biff");
        assertEquals(xmlValError.getOffendingQName().getLocalPart(), "q");
        assertEquals(xmlValError.getMessage(), "Expected element 'a@http://openuri.org/bobschema' instead of 'q@http://openuri.org/bobschema' here in element foo@http://openuri.org/bobschema");
    }
}

@Test
void testValidationAttributeError() throws XmlException {
    String empSchema = "<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'   elementFormDefault='qualified'>
" + "<xs:element name='age'>
" + "<xs:simpleType>
" + "<xs:restriction base='xs:integer'>
" + "<xs:minInclusive value='0'/>
" + "<xs:maxInclusive value='100'/>
" + "</xs:restriction>
" + "</xs:simpleType>
" + "</xs:element>
" + "<xs:element name='empRecords'>
" + "<xs:complexType>
" + "<xs:sequence>
" + "<xs:element name='person' type='personType' maxOccurs='unbounded'/>
" + "</xs:sequence>
" + "</xs:complexType>
" + "</xs:element>
" + "<xs:element name='name' type='xs:string'/>
" + "<xs:complexType name='personType'>
" + "<xs:sequence>
" + "<xs:element ref='name'/>
" + "<xs:element ref='age'/>
" + "</xs:sequence>
" + "<xs:attribute name='employee' use='required'>
" + "<xs:simpleType>
" + "<xs:restriction base='xs:NMTOKEN'>
" + "<xs:enumeration value='current'/>
" + "<xs:enumeration value='past'/>
" + "</xs:restriction>
" + "</xs:simpleType>
" + "</xs:attribute>
" + "</xs:complexType>
" + "</xs:schema>
";
    String[] schemas = { empSchema };
    String xmlInstance = "<empRecords xmlns:xsi='http://www.w3.org/2001/XMLSchema-instance' >" + "<person employee='past'>" + "<name>joe blow</name>" + "<age>31</age>" + "</person>" + "<person>" + "<name>test user</name>" + "<age>29</age>" + "</person>" + "</empRecords>";
    List<XmlError> errors = performValidation(schemas, xmlInstance);
    assertNotNull(errors);
    assertFalse(errors.isEmpty());
    for (Object error : errors) {
