@Test
void testValidate0() throws Exception {
    //
    // The most basic schema
    //
    String schema = "<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'>\n" + "</xs:schema>";
    String[] schemas = { schema };
    SchemaTypeLoader stl = makeSchemaTypeLoader(schemas);
    //
    // One which uses ##targetNamespace on a wildcard
    //
    schema = "<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'>\n" + "  <xs:complexType name='foo'>\n" + "    <xs:sequence>\n" + "      <xs:any namespace='##targetNamespace'/>\n" + "    </xs:sequence>\n" + "  </xs:complexType>\n" + "</xs:schema>";
    String[] schemas99 = { schema };
    stl = makeSchemaTypeLoader(schemas99);
    //
    // A big, nasty schema :-)
    //
    File schemeFile = JarUtil.getResourceFromJarasFile("xbean/xmlobject/store/XMLSchema.xsd");
    File xmlFile = JarUtil.getResourceFromJarasFile("xbean/xmlobject/store/XML.xsd");
    File[] schemasF = { schemeFile, xmlFile };
    stl = makeSchemaTypeLoader(schemasF);
    SchemaType type = stl.findDocumentType(new QName("http://www.w3.org/2001/XMLSchema", "schema"));
    assertNotNull(type);
    //
    // A good piece from a J2EE schema
    //
    schema = "<?xml version='1.0' encoding='UTF-8'?>\n" + "<xsd:schema xmlns='http://www.w3.org/2001/XMLSchema'\n" + "     xmlns:xsd='http://www.w3.org/2001/XMLSchema'\n" + "     elementFormDefault='qualified'\n" + "     attributeFormDefault='unqualified'>\n" + "<xsd:annotation>\n" + "<xsd:documentation>\n" + "@(#)application-client_1_4.xsds	1.7 07/08/02\n" + "</xsd:documentation>\n" + "</xsd:annotation>\n" + "</xsd:schema>\n";
    String[] schemas5 = { schema };
    stl = makeSchemaTypeLoader(schemas5);
    //
    // A bad schema
    //
    schema = "<foo/>";
    String[] schemas2 = { schema };
    assertThrows(Exception.class, () -> makeSchemaTypeLoader(schemas2));
    //
    // A bad schema
    //
    schema = "<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'>\n" + "  <foo/>\n" + "</xs:schema>";
    String[] schemas3 = { schema };
    assertThrows(Exception.class, () -> makeSchemaTypeLoader(schemas3));
}

@Test
void testValidate5() throws Exception {
    String schema = "<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'>\n" + "\n" + "  <xs:element name='hee'>\n" + "    <xs:complexType>\n" + "      <xs:sequence>\n" + "        <xs:element name='haw' type='xs:int'/>\n" + "      </xs:sequence>\n" + "      <xs:attribute name='yee' type='xs:int'/>\n" + "    </xs:complexType>\n" + "  </xs:element>\n" + "\n" + "  <xs:simpleType name='kindaPrime'>\n" + "    <xs:restriction base='xs:decimal'>\n" + "      <xs:pattern value='[0-9]*[13579]'/>\n" + "      <xs:enumeration value='3'/>\n" + "      <xs:enumeration value='5'/>\n" + "      <xs:enumeration value='7'/>\n" + "      <xs:enumeration value='11'/>\n" + "      <xs:enumeration value='13'/>\n" + "      <xs:enumeration value='17'/>\n" + "      <xs:enumeration value='19'/>\n" + "    </xs:restriction>\n" + "  </xs:simpleType>\n" + "\n" + "</xs:schema>\n" + "";
    String[] schemas = { schema };
    SchemaTypeLoader stl = makeSchemaTypeLoader(schemas);
    XmlObject x = stl.parse("<hee yee='3'><haw>66</haw></hee>", null, null);
    try (XmlCursor c = x.newCursor()) {
        do {
            XmlObject obj = c.getObject();
            if (obj != null) {
                obj.validate();
            }
        } while (!c.toNextToken().isNone());
    }
    // invalid
    x = stl.parse("<hee yee='five'><haw>66</haw></hee>", null, null);
    assertFalse(x.validate());
    try (XmlCursor c = x.newCursor()) {
        c.toNextToken();
        c.toNextToken();
        assertFalse(c.getObject().validate());
    }
    // No schema
    x = XmlObject.Factory.parse("<foo x='y'>asas<bar>asas</bar></foo>");
    try (XmlCursor c = x.newCursor()) {
        do {
            XmlObject obj = c.getObject();
            if (obj != null) {
                obj.validate();
            }
        } while (!c.toNextToken().isNone());
    }
}

