@Test
void testValidateBase64() {
    assertArrayEquals(new byte[0], JavaBase64Holder.lex("", null));
    final java.util.Random rnd = new java.util.Random();
    final byte[] bytes = new byte[1024];
    rnd.nextBytes(bytes);
    assertArrayEquals(bytes, JavaBase64Holder.lex(Base64.getEncoder().encodeToString(bytes), null));
    assertArrayEquals(bytes, JavaBase64Holder.lex(Base64.getMimeEncoder().encodeToString(bytes), null));
    assertArrayEquals(bytes, JavaBase64Holder.lex(Base64.getMimeEncoder(16, "\n".getBytes(StandardCharsets.UTF_8)).encodeToString(bytes), null));
}

@Test
void testPath() throws XmlException {
    final XmlObject obj = XmlObject.Factory.parse("<a>" + "<b>" + "<c>val1</c>" + "<d><c>val2</c></d>" + "</b>" + "<c>val3</c>" + "</a>");
    try (XmlCursor c = obj.newCursor()) {
        c.selectPath(".//b/c");
        int selCount = c.getSelectionCount();
        assertEquals(1, selCount, "SelectionCount");
        while (c.hasNextSelection()) {
            c.toNextSelection();
            assertTrue(c.isStart(), "OnStartElement");
            assertEquals("val1", c.getTextValue(), "TextValue");
        }
    }
}

