/**
 * Simple Compilation Tests - If the methods are not present,
 * - this class won't compile
 * Ensures method getSourceName is on SchemaComponent and
 * can be called from SchemaGlobalElement and SchemaGlobalAttribute
 */
@Test
void test199585() throws Exception {
    String str = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n" + "<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\"\n" + "    targetNamespace=\"urn:lax.Doc.Compilation\"\n" + "    xmlns:tns=\"urn:lax.Doc.Compilation\"\n" + "    xmlns:pre=\"noResolutionNamespace\"\n" + "    elementFormDefault=\"qualified\"\n" + "    attributeFormDefault=\"unqualified\">\n" + "   <xs:attribute name=\"GlobalAtt\" type=\"xs:string\" />\n" + "   <xs:element name=\"QuantityElement\" type=\"tns:quantity\" />\n" + "   <xs:simpleType name=\"quantity\">\n" + "    <xs:restriction base=\"xs:NMTOKEN\">\n" + "      <xs:enumeration value=\"all\"/>\n" + "      <xs:enumeration value=\"most\"/>\n" + "      <xs:enumeration value=\"some\"/>\n" + "      <xs:enumeration value=\"few\"/>\n" + "      <xs:enumeration value=\"none\"/>\n" + "    </xs:restriction>\n" + "  </xs:simpleType>" + "</xs:schema>";
    XmlObject[] schemas = { XmlObject.Factory.parse(str) };
    XmlOptions xOpt = new XmlOptions().setValidateTreatLaxAsSkip();
    SchemaTypeSystem sts = XmlBeans.compileXmlBeans(null, null, schemas, null, XmlBeans.getBuiltinTypeSystem(), null, xOpt);
    //ensure SchemaGlobalElement has getSourceName Method
    SchemaGlobalElement[] els = sts.globalElements();
    assertEquals(1, els.length);
    assertDoesNotThrow(els[0]::getSourceName);
    //ensure SchemaGlobalAttribute has getSourceName Method
    SchemaGlobalAttribute[] ats = sts.globalAttributes();
    assertEquals(1, ats.length);
    assertDoesNotThrow(ats[0]::getSourceName);
}

