@Test
void testQNameSets() {
    int iterations = 10000;
    int seed = 0;
    Random rnd = new Random(seed);
    String[] localname = { "a", "b", "c", "d", "e" };
    String[] namespace = { "n1", "n2", "n3", "n4", "n5" };
    int width = localname.length;
    QName[] name = new QName[width * namespace.length];
    for (int i = 0; i < width; i++) {
        for (int j = 0; j < namespace.length; j++) {
            name[i + width * j] = new QName(namespace[j], localname[i]);
        }
    }
    // stack of sets
    Stack<QNameSetBuilder> teststack = new Stack<QNameSetBuilder>();
    // stack of boolean arrays
    Stack<boolean[]> trackstack = new Stack<boolean[]>();
    QNameSetBuilder current = new QNameSetBuilder();
    boolean[] contents = new boolean[width * namespace.length];
    boolean[] temp;
    int i = 0;
    int j = 0;
    for (int l = 0; l < iterations; l++) {
        // apply a random operation
        if (rnd.nextInt(3) != 0) {
            // don't do the last one for isAll test
            i = rnd.nextInt(width - 1);
            // don't do the last one for isAll test
            j = rnd.nextInt(namespace.length - 1);
        }
        switch(teststack.size() < 1 ? 24 : rnd.nextInt(iterations - l > teststack.size() ? 24 : 5)) {
            default:
                // new
                teststack.push(current);
                trackstack.push(contents);
                current = new QNameSetBuilder();
                contents = new boolean[width * namespace.length];
                break;
            case 19:
            case 20:
            case 22:
                // random
                teststack.push(current);
                trackstack.push(contents);
                current = new QNameSetBuilder();
                contents = new boolean[width * namespace.length];
                if (rnd.nextInt(2) == 0) {
                    current.invert();
                    for (int k = 0; k < width; k++) {
                        contents[k + width * (namespace.length - 1)] = true;
                    }
                }
                for (int h = 0; h < namespace.length - 1; h++) {
                    if (rnd.nextInt(2) == 0)
                        current.removeNamespace(namespace[h]);
                    else {
                        current.addNamespace(namespace[h]);
                        contents[width - 1 + width * h] = true;
                    }
                    for (int k = 0; k < width - 1; k++) {
                        if (rnd.nextInt(2) == 0)
                            current.remove(name[k + width * h]);
                        else {
                            current.add(name[k + width * h]);
                            contents[k + width * h] = true;
                        }
                    }
                }
                break;
            case 0:
                // add set
                current.addAll(teststack.pop());
                temp = trackstack.pop();
                for (int k = 0; k < width * namespace.length; k++) if (temp[k])
                    contents[k] = true;
                break;
            case 1:
                // remove set
                current.removeAll(teststack.pop());
                temp = trackstack.pop();
                for (int k = 0; k < width * namespace.length; k++) if (temp[k])
                    contents[k] = false;
                break;
            case 2:
                // restrict set
                current.restrict(teststack.pop());
                temp = trackstack.pop();
                for (int k = 0; k < width * namespace.length; k++) if (!temp[k])
                    contents[k] = false;
                break;
            case 3:
                // union
                current = new QNameSetBuilder(current.union(teststack.pop()));
                temp = trackstack.pop();
                for (int k = 0; k < width * namespace.length; k++) if (temp[k])
                    contents[k] = true;
                break;
            case 4:
                // intersect
                current = new QNameSetBuilder(current.intersect(teststack.pop()));
                temp = trackstack.pop();
                for (int k = 0; k < width * namespace.length; k++) if (!temp[k])
                    contents[k] = false;
                break;
            case 5:
                // copy
                current = new QNameSetBuilder(current);
                break;
            case 6:
            case 7:
            case 8:
                // add one + name[i + width * j];
                current.add(name[i + width * j]);
                contents[i + width * j] = true;
                break;
            case 9:
            case 10:
            case 11:
                // remove one + name[i + width * j];
                current.remove(name[i + width * j]);
                contents[i + width * j] = false;
                break;
            case 12:
            case 13:
                // add namespace + namespace[j];
                current.addNamespace(namespace[j]);
                for (int k = 0; k < width; k++) contents[k + width * j] = true;
                break;
            case 14:
            case 15:
                // remove namespace + namespace[j];
                current.removeNamespace(namespace[j]);
                for (int k = 0; k < width; k++) contents[k + width * j] = false;
                break;
            case 16:
            case 17:
                // invert
                current.invert();
                for (int k = 0; k < width * namespace.length; k++) contents[k] = !contents[k];
                break;
            case 18:
                // inverse
                current = new QNameSetBuilder(current.inverse());
                for (int k = 0; k < width * namespace.length; k++) contents[k] = !contents[k];
                break;
        }
        // System.out.println(format(teststack.size(), l, label, current));
        // then, verify current matches contents
        int count = 0;
        for (int k = 0; k < width * namespace.length; k++) {
            assertTrue((current.contains(name[k]) == contents[k]), format(l, "Content mismatch " + name[k], current));
            if (contents[k])
                count++;
        }
        assertTrue(((count == 0) == current.isEmpty()), format(l, "ERROR: isEmpty is wrong", current));
        assertEquals((count == width * namespace.length), current.isAll(), format(l, "ERROR: isAll is wrong", current));
        // test isDisjoint and containsAll
        if (teststack.size() >= 1) {
            boolean disjoint = true;
            temp = trackstack.peek();
            for (int k = 0; k < width * namespace.length; k++) {
                if (temp[k] && contents[k]) {
                    disjoint = false;
                    break;
                }
            }
            assertEquals(disjoint, current.isDisjoint(teststack.peek()), format(l, "ERROR: disjoint is wrong", current));
            boolean containsAll = true;
            for (int k = 0; k < width * namespace.length; k++) {
                if (temp[k] && !contents[k]) {
                    containsAll = false;
                    break;
                }
            }
            assertEquals(containsAll, current.containsAll(teststack.peek()), format(l, "ERROR: containsAll is wrong", current));
        }
    }
}

